import { HttpErrorResponse, HttpResponse } from '@angular/common/http';
import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { patient } from '../../model/patient';
import { PatientService } from '../../services/patient.service';

@Component({
  selector: 'app-patient',
  templateUrl: './patient.component.html',
  styleUrls: ['./patient.component.css']
})
export class PatientComponent implements OnInit {
  numberitem = 10
  id: String;
  public name: String
  constructor(private patientservice: PatientService, private router: Router) { }

  ngOnInit(): void { this.get_patients() }

  patients: patient[];
  totallength: any;
  page: number = 1;
  content: boolean;
  config = "| paginate : {itemsPerPage :10, currentPage : page ,totalItems : totallength} | filter:id";

  get_patients() {

    this.patientservice.get_patients().subscribe(
      data => {
        if (data.status == 200) {
          this.patients = data.body,
            this.totallength = this.patients.length;
          this.content = true;
        }
        else if (data.status == 204) {
          this.content = false;
        }
      },
      (error: HttpErrorResponse) => {
        if (error.status == 403) {
          localStorage.clear();
          this.patientservice.clear();
          this.router.navigateByUrl('/login');
        }
      }
    )
  }

  pass(patientidentifier: string) {
    localStorage.setItem('patientidentifier', patientidentifier);
    this.router.navigateByUrl('/dossier');
  }
  id1: string
  search() {
    if (this.id1 == "") {
      this.ngOnInit();
    }
    else {
      this.patients = this.patients.filter(res => {
        return res.patientidentifier.match(this.id1);
      })
      this.totallength = this.patients.length;
      if (this.totallength == 0) {
        this.content = false;

      }
    }
  }



  tt(): void {
    if (this.id.length == 0)
      this.numberitem = 10
    else
      this.numberitem = this.totallength;
  }


}
